alter table public.programs alter column university_id drop not null;
alter table public.programs
  add column if not exists icon text,
  add column if not exists overview text,
  add column if not exists eligibility_criteria text,
  add column if not exists degree_options text[] not null default '{}',
  add column if not exists required_subjects text[] not null default '{}',
  add column if not exists entry_tests text[] not null default '{}',
  add column if not exists syllabus text[] not null default '{}',
  add column if not exists subject_weightage jsonb not null default '{}'::jsonb,
  add column if not exists preparation_duration text,
  add column if not exists preparation_plan text[] not null default '{}';

create table if not exists public.program_universities (
  program_id uuid not null references public.programs(id) on delete cascade,
  university_id uuid not null references public.universities(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (program_id, university_id)
);
create table if not exists public.program_mock_tests (
  program_id uuid not null references public.programs(id) on delete cascade,
  mock_test_id uuid not null references public.mock_tests(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (program_id, mock_test_id)
);
alter table public.program_universities enable row level security;
alter table public.program_mock_tests enable row level security;
drop policy if exists "Published program universities are readable" on public.program_universities;
create policy "Published program universities are readable" on public.program_universities for select to anon, authenticated using (exists(select 1 from public.programs p where p.id=program_id and p.status='published'));
drop policy if exists "Admins manage program universities" on public.program_universities;
create policy "Admins manage program universities" on public.program_universities for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists "Published program tests are readable" on public.program_mock_tests;
create policy "Published program tests are readable" on public.program_mock_tests for select to anon, authenticated using (exists(select 1 from public.programs p where p.id=program_id and p.status='published'));
drop policy if exists "Admins manage program tests" on public.program_mock_tests;
create policy "Admins manage program tests" on public.program_mock_tests for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));

