on conflict (slug) do update set name=excluded.name,description=excluded.description,status=excluded.status,icon=excluded.icon,overview=excluded.overview,eligibility_criteria=excluded.eligibility_criteria,degree_options=excluded.degree_options,required_subjects=excluded.required_subjects,entry_tests=excluded.entry_tests,syllabus=excluded.syllabus,subject_weightage=excluded.subject_weightage,preparation_duration=excluded.preparation_duration,preparation_plan=excluded.preparation_plan,updated_at=now();
